mapper.select:

WHERE 1=1

    AND UPPER(ue.uned_nombre) LIKE UPPER(#{nombre})


    AND ue.uned_rbd = #{rbd}



    ORDER BY #{orderBy} ${order}


    LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(ue.pk_uned_id_unidad_educativa) FROM unidad_educativa ue LEFT JOIN programa p ON p.pk_prog_id_programa = ue.fk_uned_id_programa LEFT JOIN modalidad m ON m.pk_moda_id_modalidad = ue.fk_ue_id_modalidad LEFT JOIN mecanismo_financiamiento mf ON mf.pk_mefi_id_mecanismo_financiamiento = ue.fk_uned_id_mecanismo_financiamiento LEFT JOIN sostenedor s ON s.pk_sost_id_sostenedor = ue.fk_uned_id_sostenedor LEFT JOIN estado_unidad_educativa eue ON eue.pk_eued_id_estado_unidad_educativa = ue.fk_uned_id_estado_unidad_educativa LEFT JOIN genero g ON g.pk_gener_id_genero = ue.fk_uned_id_genero LEFT JOIN estado_funcionamiento_ensenianza efe ON efe.pk_efen_id_estado_funcionamiento_ensenianza = ue.fk_uned_id_estado_funcionamiento_ensenianza WHERE TRUE
AND UPPER(ue.uned_nombre) LIKE UPPER(#{nombre})
AND ue.uned_rbd = #{rbd}
